class MarkdownContext:
    """Manages the console render state."""

    def __init__(
        self,
        console: Console,
        options: ConsoleOptions,
        style: Style,
        inline_code_lexer: str | None = None,
        inline_code_theme: str = "monokai",
    ) -> None:
        self.console = console
        self.options = options
        self.style_stack: StyleStack = StyleStack(style)
        self.stack: Stack[MarkdownElement] = Stack()

        self._syntax: Syntax | None = None
        if inline_code_lexer is not None:
            self._syntax = Syntax("", inline_code_lexer, theme=inline_code_theme)

    @property
    def current_style(self) -> Style:
        """Current style which is the product of all styles on the stack."""
        return self.style_stack.current

    def on_text(self, text: str, node_type: str) -> None:
        """Called when the parser visits text."""
        if node_type in {"fence", "code_inline"} and self._syntax is not None:
            highlight_text = self._syntax.highlight(text)
            highlight_text.rstrip()

def _extract_endpoint_context(func: Any) -> EndpointContext:
    """Extract endpoint context with caching to avoid repeated file I/O."""
    func_id = id(func)

    if func_id in _endpoint_context_cache:
        return _endpoint_context_cache[func_id]

    try:
        ctx: EndpointContext = {}

        if (source_file := inspect.getsourcefile(func)) is not None:
            ctx["file"] = source_file
        if (line_number := inspect.getsourcelines(func)[1]) is not None:
            ctx["line"] = line_number
        if (func_name := getattr(func, "__name__", None)) is not None:
            ctx["function"] = func_name
    except Exception:
        ctx = EndpointContext()

    _endpoint_context_cache[func_id] = ctx
    return ctx

def strip_links(cls, segments: Iterable["Segment"]) -> Iterable["Segment"]:
    """Remove all links from an iterable of styles.

    Args:
        segments (Iterable[Segment]): An iterable segments.

    Yields:
        Segment: Segments with link removed.
    """
    for segment in segments:
        if segment.control or segment.style is None:
            yield segment
        else:
            text, style, _control = segment
            yield cls(text, style.update_link(None) if style else None)

def prepare_headers(self, headers):
    """Prepares the given HTTP headers."""

    self.headers = CaseInsensitiveDict()
    if headers:
        for header in headers.items():
            # Raise exception on invalid header value.
            check_header_validity(header)
            name, value = header
            self.headers[to_native_string(name)] = value

def append(
    self, text: Union["Text", str], style: Optional[Union[str, "Style"]] = None
) -> "Text":
    """Add text with an optional style.

    Args:
        text (Union[Text, str]): A str or Text to append.
        style (str, optional): A style name. Defaults to None.

    Returns:
        Text: Returns self for chaining.
    """

    if not isinstance(text, (str, Text)):
        raise TypeError("Only str or Text can be appended to Text")

    if len(text):
        if isinstance(text, str):
            sanitized_text = strip_control_codes(text)
            self._text.append(sanitized_text)
            offset = len(self)
            text_length = len(sanitized_text)
            if style:
                self._spans.append(Span(offset, offset + text_length, style))
            self._length += text_length
        elif isinstance(text, Text):
            _Span = Span
            if style is not None:
                raise ValueError(
                    "style must not be set when appending Text instance"

def get_schema_from_model_field(
    *,
    field: ModelField,
    model_name_map: ModelNameMap,
    field_mapping: dict[
        tuple[ModelField, Literal["validation", "serialization"]], JsonSchemaValue
    ],
    separate_input_output_schemas: bool = True,
) -> dict[str, Any]:
    override_mode: Union[Literal["validation"], None] = (
        None
        if (separate_input_output_schemas or _has_computed_fields(field))
        else "validation"
    )
    field_alias = (
        (field.validation_alias or field.alias)
        if field.mode == "validation"
        else (field.serialization_alias or field.alias)
    )

    # This expects that GenerateJsonSchema was already used to generate the definitions
    json_schema = field_mapping[(field, override_mode or field.mode)]
    if "$ref" not in json_schema:
        # TODO remove when deprecating Pydantic v1
        # Ref: https://github.com/pydantic/pydantic/blob/d61792cc42c80b13b23e3ffa74bc37ec7c77f7d1/pydantic/schema.py#L207
        json_schema["title"] = field.field_info.title or field_alias.title().replace(
            "_", " "
        )
    return json_schema

def _render_buffer(self, buffer: Iterable[Segment]) -> str:
    """Render buffered output, and clear buffer."""
    output: List[str] = []
    append = output.append
    color_system = self._color_system
    legacy_windows = self.legacy_windows
    not_terminal = not self.is_terminal
    if self.no_color and color_system:
        buffer = Segment.remove_color(buffer)
    for text, style, control in buffer:
        if style:
            append(
                style.render(
                    text,
                    color_system=color_system,
                    legacy_windows=legacy_windows,
                )
            )
        elif not (not_terminal and control):
            append(text)

    rendered = "".join(output)
    return rendered

